export const DEMO_SHELL_LAYER_CSS = `
@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-be-vietnam-pro), "Be Vietnam Pro", ui-sans-serif, system-ui, sans-serif;
    font-weight: 400;
  }
  html {
    @apply font-sans;
    scroll-behavior: smooth;
  }
  .font-heading {
    font-family: var(--font-heading);
    letter-spacing: -0.01em;
  }
}
@layer utilities {
  .chungdoi-scroll {
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(0, 0, 0, 0.2) transparent;
    touch-action: pan-y;
  }
  .chungdoi-scroll::-webkit-scrollbar {
    width: 4px;
  }
  .chungdoi-scroll::-webkit-scrollbar-track {
    background: transparent;
  }
  .chungdoi-scroll::-webkit-scrollbar-thumb {
    background-color: rgba(0, 0, 0, 0.2);
    border-radius: 2px;
  }
  .chungdoi-scroll::-webkit-scrollbar-thumb:hover {
    background-color: rgba(0, 0, 0, 0.3);
  }

  /* Dải điều hướng ngang của admin dưới breakpoint lg. Có 13 mục nên nó luôn
     tràn trên điện thoại, và thanh scroll ngang nằm dưới hàng pill trông như
     giao diện bị lỗi. Ẩn thanh scroll đi, rồi thay tín hiệu "còn cuộn được"
     bằng vệt mờ ở đúng phía còn nội dung — hai data attribute do JS bật/tắt
     theo scrollLeft.

     Fade 0px nghĩa là gradient chuyển từ transparent sang đen trong khoảng
     rộng 0, tức không có vệt mờ nào — nên trạng thái mặc định (không tràn)
     nhìn y như khi chưa có mask. */
  .admin-nav-strip {
    --admin-nav-fade-start: 0px;
    --admin-nav-fade-end: 0px;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
    -webkit-mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 var(--admin-nav-fade-start),
      #000 calc(100% - var(--admin-nav-fade-end)),
      transparent 100%
    );
    mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 var(--admin-nav-fade-start),
      #000 calc(100% - var(--admin-nav-fade-end)),
      transparent 100%
    );
  }

  .admin-nav-strip::-webkit-scrollbar {
    display: none;
  }

  .admin-nav-strip[data-overflow-start="true"] {
    --admin-nav-fade-start: 24px;
  }

  .admin-nav-strip[data-overflow-end="true"] {
    --admin-nav-fade-end: 24px;
  }

  /* Bảng quản trị: xem \`src/components/admin-table-scroller.tsx\` để biết vì sao
     thanh cuộn thật của bảng bị ẩn và thay bằng một thanh ghim ở đáy màn hình.

     Chỉ ẩn khi \`data-proxy="on"\` — cờ do component bật sau khi gắn. Trước lúc
     đó (HTML từ server, hoặc JS lỗi) bảng vẫn giữ thanh cuộn gốc. */
  .admin-table-viewport {
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
  }

  .admin-table-viewport[data-proxy="on"] {
    scrollbar-width: none;
  }

  .admin-table-viewport[data-proxy="on"]::-webkit-scrollbar {
    height: 0;
    display: none;
  }

  /* macOS ẩn thanh cuộn overlay khi đứng yên, nên để mặc định thì thanh ghim
     này vô hình đúng lúc cần nhìn thấy nhất. Khai báo \`::-webkit-scrollbar\`
     buộc WebKit/Blink chuyển sang thanh luôn hiện. */
  .admin-table-scrollbar {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklab, var(--muted-foreground) 55%, transparent)
      transparent;
  }

  .admin-table-scrollbar::-webkit-scrollbar {
    height: 12px;
    -webkit-appearance: none;
    appearance: none;
  }

  .admin-table-scrollbar::-webkit-scrollbar-track {
    background-color: transparent;
  }

  /* Viền trong suốt + \`background-clip: content-box\` là cách thu nút kéo lại
     cho mảnh mà vẫn giữ nguyên vùng bấm 12px. */
  .admin-table-scrollbar::-webkit-scrollbar-thumb {
    border: 3px solid transparent;
    border-radius: 9999px;
    background-clip: content-box;
    background-color: color-mix(in oklab, var(--muted-foreground) 55%, transparent);
  }

  .admin-table-scrollbar::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklab, var(--muted-foreground) 85%, transparent);
  }

  /* Cột ghim. Kéo ngang mà cột danh tính trôi đi thì đọc được ô bên phải cũng
     không biết nó thuộc dòng nào, nên cột đầu và cột thao tác đứng yên.

     Chỉ từ 48rem trở lên: trên điện thoại, hai cột ghim chiếm gần hết chiều
     ngang và phần cuộn được còn lại chỉ vài chục pixel — tệ hơn là không ghim. */
  @media (min-width: 48rem) {
    /* Nền phải đục: \`sticky\` không cắt nội dung phía dưới, nó chỉ nằm trên. */
    .admin-col-pin-start,
    .admin-col-pin-end {
      position: sticky;
      z-index: 1;
      background-color: var(--background);
    }

    .admin-col-pin-start {
      left: 0;
    }

    .admin-col-pin-end {
      right: 0;
    }

    /* \`thead\` tô \`bg-muted/40\`, tức nửa trong suốt. Ô ghim cần chính màu đã hoà
       lên nền, chứ lấy \`var(--muted)\` trần là header sẽ lệch tông hai bên. */
    .admin-table-viewport thead .admin-col-pin-start,
    .admin-table-viewport thead .admin-col-pin-end {
      z-index: 2;
      background-color: color-mix(in oklab, var(--muted) 40%, var(--background));
    }

    /* Nền đục của ô ghim phủ mất đường kẻ dưới của hàng, nên vẽ lại bằng shadow
       bên trong ô. */
    .admin-table-viewport tbody tr:not(:last-child) .admin-col-pin-start,
    .admin-table-viewport tbody tr:not(:last-child) .admin-col-pin-end {
      box-shadow: inset 0 -1px 0 var(--border);
    }

    /* Vệt đổ chỉ hiện ở phía còn nội dung bị che, để lúc bảng vừa khung thì cột
       ghim nhìn y như cột thường. */
    .admin-table-viewport[data-overflow-start="true"] .admin-col-pin-start::after,
    .admin-table-viewport[data-overflow-end="true"] .admin-col-pin-end::after {
      content: "";
      position: absolute;
      top: 0;
      bottom: 0;
      width: 12px;
      pointer-events: none;
    }

    .admin-table-viewport[data-overflow-start="true"] .admin-col-pin-start::after {
      left: 100%;
      background: linear-gradient(
        to right,
        color-mix(in oklab, var(--foreground) 12%, transparent),
        transparent
      );
    }

    .admin-table-viewport[data-overflow-end="true"] .admin-col-pin-end::after {
      right: 100%;
      background: linear-gradient(
        to left,
        color-mix(in oklab, var(--foreground) 12%, transparent),
        transparent
      );
    }
  }

  .font-pattaya {
    font-family: "Pattaya", cursive;
  }

  .font-wedding {
    font-family: "Fz Aghita", "Pattaya", cursive;
  }

  .font-qellia {
    font-family: "Fz Qellia", "Times New Roman", serif;
  }

  .line-clamp-2 {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
}
`;
